// TH18 v1.00a Extra stage07 wave: st07.ecl.txt::MainSub00:1148-1171
// Dependencies: GirlA01:229-246, GirlA01_at:248-272, GirlBlueA01:567-573.
// Source wave schedule is 720 frames; 120-frame opening buffer is inside the card.

const TIME_LIMIT: int = 2180;
const OPENING_BUFFER: int = 120;
const TH18_BALL2: int = 432;             // etSprite type 5 (bullet-types.md row base 352+5*16)
const BULLET_COLOR: int = 6;             // etSprite(0, 5, 6)
const BULLET_SPEED: fx = 3.2fx;          // etSpeed(0, 3.2f, 1.0f), single layer
const BULLET_ANIM_BACK: fx = 12.8fx;     // ANIM birth offset -4*velocity (ex-effects.md)

// st07.ecl.txt:248-272 GirlA01_at
// A=10 groups; each group is three etOn shots 15 frames apart, then wait(40).
// Config is etAim(0,0) one aimed bullet, etSprite(0,5,6), etSpeed(0,3.2,1.0),
// etCount(0,1,1), etEx(0,0,2,1,...): ANIM a=1, visual only; its birth
// backward displacement is kept below, while the birth no-judgment window is
// omitted by transcription-policy.md.
async sub girl_fire() {
    for group in 0..10 {
        for shot in 0..3 {
            var a: angle = aim_player();
            var bx: fx = $self_x - BULLET_ANIM_BACK * cos(a);
            var by: fx = $self_y - BULLET_ANIM_BACK * sin(a);
            _ = fire(TH18_BALL2, BULLET_COLOR, bx, by, BULLET_SPEED, a, none, none);
            wait(15);
        }
        wait(40);
    }
}

// st07.ecl.txt:229-246 GirlA01 / 567-573 GirlBlueA01
// GirlBlueA01 only adds presentation ANM selection before the same GirlA01 call;
// that presentation is omitted. mirror is the child mirror bit from
// enmCreate (0) / enmCreateM (1); normal moveVel/moveVelTime mirror the angle.
async sub girl_blue(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);                   // setHurtbox(24,24) -> radius 24*0.5
    set_hitbox(8fx);                     // setHitbox(16,16)  -> radius 16*0.5
    spawn girl_fire();
    move_vel(0, 90deg, 0.8fx, EASE_LINEAR);   // moveVel(pi/2, 0.8)
    wait(60);
    var turn: angle = 22.5deg;                 // moveVelTime target pi/8
    if mirror != 0 { turn = 157.5deg; }        // mirrored angle = pi - pi/8
    move_vel(240, turn, 1.2fx, EASE_QUAD_IN);  // 405 mode1 = t^2 on angle and speed
    wait(240);
    loop { wait(1000); }                       // source GirlA01_284/304 idle loop
}

// st07.ecl.txt:1148-1171 MainSub00
// Six rounds; each round creates three left (enmCreate, mirror 0) then three
// right (enmCreateM, mirror 1) at 20-frame intervals = 120 frames per round.
async sub pattern() {
    wait(OPENING_BUFFER);
    for round in 0..6 {
        for li in 0..3 {
            var dxl: fx = ((rand(65536) - 32768) as fx / 32768) * 32fx;
            _ = spawn_enemy(-110fx + dxl, -32fx, 200, 0, 0, 0, girl_blue(0));
            wait(20);
        }
        for ri in 0..3 {
            var dxr: fx = ((rand(65536) - 32768) as fx / 32768) * 32fx;
            _ = spawn_enemy(110fx + dxr, -32fx, 200, 0, 0, 0, girl_blue(1));
            wait(20);
        }
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
